#include <iostream>
#include <iomanip>

void print_amount(long long cents) {
    if (cents < 0) { std::cout << '-'; cents = -cents; }
    std::cout << cents / 100 << '.' << std::setfill('0')
              << std::setw(2) << cents % 100 << '\n';
}
int main() {
    print_amount(5);
    print_amount(-1234);
}

#include <iostream>
#include <sstream>

void summarize(std::istream& input) {
    int count = 0;
    long long sum = 0;
    while (true) {
        input >> std::ws;
        if (input.eof()) break;
        int value{};
        if (!(input >> value) || value < -1000 || value > 1000 || count == 100) {
            std::cout << "ОШИБКА\n";
            return;
        }
        ++count;
        sum += value;
    }
    std::cout << count << ' ' << sum << '\n';
}
int main() {
    std::istringstream input{"10 -2 4"};
    summarize(input);
}

#include <iostream>
#include <string>

void split_command(const std::string& text) {
    std::size_t count = 1;
    for (char ch : text) if (ch == ';') ++count;
    std::cout << count << '\n';
    std::size_t start = 0;
    while (true) {
        const auto end = text.find(';', start);
        std::cout << text.substr(start, end == std::string::npos ? end : end - start) << '\n';
        if (end == std::string::npos) break;
        start = end + 1;
    }
}
int main() {
    split_command("a;;b;");
}

